#!/bin/sh
set -eu

# Mount the config directory, not a file generated by another container.
# Docker creates missing short-syntax file bind sources as directories before
# depends_on has run init-configs. A symlink also observes later bootstrap writes.
# Nginx runs unprivileged and cannot traverse /root, even when the file is readable.
config="/aio-config/localStorage.json"
if [ ! -f "$config" ]; then
    echo "[Stremio Web] Missing localStorage.json; run init-configs first." >&2
    exit 1
fi
ln -sf "$config" /srv/stremio-server/build/aio-seed.json
cp /srv/stremio-server/localStorage.json /srv/stremio-server/build/aio-defaults.json
# Upstream's raw-store importer cannot migrate this partial profile. Our loader
# merges only the addon into the current core's fully initialized guest profile.
rm -f /srv/stremio-server/build/localStorage.json
if ! grep -q 'aio-bootstrap.js' /srv/stremio-server/build/index.html; then
    sed -i 's|<head>|<head><script src="/aio-bootstrap.js?v=3"></script>|' /srv/stremio-server/build/index.html
fi
sed -i 's|src="/aio-bootstrap.js[^"]*"|src="/aio-bootstrap.js?v=3"|' /srv/stremio-server/build/index.html
# Invalidate upstream's precached index so returning browsers receive the loader.
sed -i 's|url:"index.html",revision:"[^"]*"|url:"index.html",revision:"aio-bootstrap-v3"|' /srv/stremio-server/build/service-worker.js
exec ./stremio-web-service-run.sh "$@"
